string log="";var original=UnityEngine.SceneManagement.SceneManager.GetActiveScene();
foreach(var guid in UnityEditor.AssetDatabase.FindAssets("t:Scene",new[]{"Assets/Scenes"})){
 string path=UnityEditor.AssetDatabase.GUIDToAssetPath(guid);
 var loaded=UnityEngine.SceneManagement.SceneManager.GetSceneByPath(path);bool opened=!loaded.isLoaded;
 if(opened)loaded=UnityEditor.SceneManagement.EditorSceneManager.OpenScene(path,UnityEditor.SceneManagement.OpenSceneMode.Additive);
 int n=0;foreach(var root in loaded.GetRootGameObjects())foreach(var death in root.GetComponentsInChildren<Character.Lifecycle.Death>(true)){
  var rig=death.transform.parent.GetComponent<Character.Control.PaddleCharacterVisual>();if(!rig)throw new System.Exception("Missing new player "+path);
  rig.Pose();if(rig.legacy.Any(r=>r&&r.enabled))throw new System.Exception("Old visible art "+path);
  n++;
 }
 log+=path+" players="+n+"\n";if(opened)UnityEditor.SceneManagement.EditorSceneManager.CloseScene(loaded,true);
}
UnityEngine.SceneManagement.SceneManager.SetActiveScene(original);
System.IO.File.WriteAllText("scripts/player-art-20261111/scenes.txt",log);UnityEngine.Debug.Log(log);
